use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.sequence();
    var rendered: List<String> = [];
    var i = 0;
    while i < signals.len() {
        match signals.get(i) {
            Some(s) => {
                let entry = match s {
                    Calm => "calm",
                    Gale(speed) => "gale:".concat(other: speed.to_text()),
                    Fog(word) => "fog:".concat(other: word),
                };
                rendered.push(item: entry);
            },
            None => {},
        }
        i = i + 1;
    }
    rendered.join(sep: ";")
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    let count = frames.len();
    while i < count {
        let frame = match frames.get(i) {
            Some(f) => f,
            None => "",
        };
        let val = match relay.feed.decode(frame) {
            Ok(v) => v,
            Err(_) => 0,
        };
        total = total + val;
        i = i + 1;
    }
    return relay.feed.emit(io: io, total: total);
}

use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        match planks.get(i) {
            Some(plank) => {
                match mill.rules.keeps(plank) {
                    true => labels.push(mill.rules.label(plank)),
                    false => unit,
                }
            },
            None => unit,
        }
        i = i + 1;
    }
    labels.join(",")
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = stable.herd.lineup();
    var entries: List<String> = [];
    var i = 0;
    while i < lineup.len() {
        let pony = match lineup.get(i) {
            Some(p) => p,
            None => return Ok(unit),
        };
        let fed_pony = stable.herd.feed(pony: pony, scoops: 3);
        let entry_text = stable.ledger.entry(fed_pony);
        entries.push(entry_text);
        i = i + 1;
    }
    let output = entries.join(",");
    io.write(text: output)?;
    return Ok(unit);
}

